<?php

declare(strict_types=1);

/*
 * Endpoints of the test PKI generated by generate.sh, served on the loopback interface of the
 * sandbox by `php -S 127.0.0.1:<port> server.php` with PKI_DIR set to its directory:
 *   POST /tsa                 RFC 3161 time-stamp responses
 *   POST /ocsp, GET /ocsp/..  OCSP responses for certificates issued by the intermediate CA
 *   GET  /crl/{root,intermediate}.crl
 *   GET  /certs/{root,intermediate}.crt
 */

$dir = (string) getenv('PKI_DIR');
$path = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH) ?: '/';

$static = [
    '/crl/root.crl' => ['root.crl', 'application/pkix-crl'],
    '/crl/intermediate.crl' => ['intermediate.crl', 'application/pkix-crl'],
    '/certs/root.crt' => ['root.der', 'application/pkix-cert'],
    '/certs/intermediate.crt' => ['intermediate.der', 'application/pkix-cert'],
];

if (isset($static[$path])) {
    [$file, $type] = $static[$path];
    header('Content-Type: '.$type);
    readfile($dir.'/'.$file);

    return true;
}

if ($path === '/health') {
    echo is_file($dir.'/.done') ? 'ok' : 'pki-missing';

    return true;
}

if ($path === '/tsa' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    respondWithOpenSsl(
        file_get_contents('php://input'),
        fn (string $in, string $out): string => sprintf(
            'openssl ts -reply -config %s -queryfile %s -out %s',
            escapeshellarg($dir.'/tsa.cnf'),
            escapeshellarg($in),
            escapeshellarg($out),
        ),
        'application/timestamp-reply',
    );

    return true;
}

if (str_starts_with($path, '/ocsp')) {
    $request = $_SERVER['REQUEST_METHOD'] === 'POST'
        ? file_get_contents('php://input')
        : base64_decode(urldecode(substr($path, strlen('/ocsp/'))), true);

    respondWithOpenSsl(
        (string) $request,
        fn (string $in, string $out): string => sprintf(
            'openssl ocsp -index %s -CA %s -rsigner %s -rkey %s -reqin %s -respout %s -ndays 7',
            escapeshellarg($dir.'/intermediate/index.txt'),
            escapeshellarg($dir.'/intermediate.crt'),
            escapeshellarg($dir.'/ocsp.crt'),
            escapeshellarg($dir.'/ocsp.key'),
            escapeshellarg($in),
            escapeshellarg($out),
        ),
        'application/ocsp-response',
    );

    return true;
}

http_response_code(404);
echo 'not found';

return true;

function respondWithOpenSsl(string $request, callable $command, string $contentType): void
{
    if ($request === '') {
        http_response_code(400);
        echo 'empty request';

        return;
    }

    $in = tempnam(sys_get_temp_dir(), 'req');
    $out = tempnam(sys_get_temp_dir(), 'res');
    file_put_contents($in, $request);

    exec($command($in, $out).' 2>&1', $output, $exitCode);
    $response = (string) file_get_contents($out);
    @unlink($in);
    @unlink($out);

    if ($exitCode !== 0 || $response === '') {
        http_response_code(500);
        error_log('openssl failed: '.implode("\n", $output));
        echo 'openssl failed';

        return;
    }

    header('Content-Type: '.$contentType);
    echo $response;
}
